--
-- Table structure for table `bt_customer`
--

CREATE TABLE `bt_customer` (
  `id` int(11) NOT NULL,
  `id_role` int(1) NOT NULL,
  `firstname` varchar(255) NOT NULL,
  `lastname` varchar(255) NOT NULL,
  `gender` varchar(1) NOT NULL COMMENT 'f: Female; m: Male',
  `date_of_birth` date NOT NULL COMMENT 'Customer Date of Birth',
  `username` varchar(255) NOT NULL,
  `image` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `password` varchar(255) NOT NULL,
  `otp` varchar(4) NOT NULL,
  `phone` varchar(255) NOT NULL,
  `email_verification_code` varchar(255) DEFAULT NULL,
  `email_verified` tinyint(1) NOT NULL,
  `mobile_verification_code` varchar(255) NOT NULL,
  `mobile_verified` tinyint(1) NOT NULL,
  `ipaddress` varchar(50) NOT NULL,
  `authKey` varchar(255) NOT NULL,
  `date_created` datetime NOT NULL,
  `created_by` int(11) NOT NULL COMMENT 'User who created the record',
  `updated_by` int(11) NOT NULL COMMENT 'User who last updated the record',
  `date_updated` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `active` tinyint(1) NOT NULL COMMENT '1: Enable; 0: Disable',
  `deleted` tinyint(1) NOT NULL DEFAULT 0,
  `offline_access` tinyint(1) NOT NULL COMMENT '1: Enable; 0: Disable',
  `email_notification` tinyint(1) NOT NULL COMMENT '1: Enable; 0: Disable',
  `address` varchar(255) NOT NULL,
  `masjid` varchar(255) DEFAULT NULL,
  `landmark` text DEFAULT NULL,
  `street` text DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `designation` text DEFAULT NULL,
  `occupation` varchar(255) NOT NULL,
  `college_name` varchar(255) DEFAULT NULL,
  `pincode` varchar(20) NOT NULL DEFAULT '',
  `company_name` text DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

