(1, 'Welcome Email', 1, 'We are excited to welcome you to Salah Time. With Salah Time, you can stay connected with masjids, programs, and prayer-time services in one place.<br/> Thank you for choosing Salah Time.', 'Salah Time', 'contact@salah-times.in', 'Welcome to Salah Time', 'contact@salah-times.in', NULL, NULL, NULL, '2026-06-25 15:39:22'),
(3, 'Email Verification', 1, 'You registered an account on Salah Time. Enter the verification OTP to activate your account.', 'Salah Time', 'contact@salah-times.in', 'Salah Time Email Verification', 'contact@salah-times.in', NULL, NULL, NULL, '2026-06-25 15:39:22'),
(4, 'Login', 1, 'We noticed a new sign-in to your Salah Time account. If this was you, you do not need to do anything. If not, please secure your account.', 'Salah Time', 'contact@salah-times.in', 'Salah Time Login Alert', 'contact@salah-times.in', NULL, NULL, NULL, '2026-06-25 15:39:22'),
(5, 'Forgot Password', 1, 'Resetting your password is easy.<br /> Enter the OTP below and choose your new password.', 'Salah Time', 'contact@salah-times.in', 'Salah Time Password Reset OTP', 'contact@salah-times.in', NULL, NULL, NULL, '2026-06-25 15:39:22'),
(6, 'Password Updated Successfully', 1, 'We are writing to inform you that your Salah Time password has been successfully updated. Your account security is our top priority, and we encourage you to keep your password safe.', 'Salah Time', 'contact@salah-times.in', 'Salah Time Password Updated', 'contact@salah-times.in', NULL, NULL, NULL, '2026-06-25 15:39:22'),
(8, 'Email Verified Successfully', 1, 'Your email address has been successfully verified on Salah Time. Thank you for helping us keep your account secure.', 'Salah Time', 'contact@salah-times.in', 'Salah Time Email Verified', 'contact@salah-times.in', NULL, NULL, NULL, '2026-06-25 15:39:22');

